({__plugin:null,__load(){if(this.__plugin)return this.__plugin;this.__plugin=function(){"use strict";let locales=unbound.i18n.createLocales({STATS_DESC:"See who talks most and when this channel is busiest, only to you",NO_MESSAGES:"No messages are loaded in this channel yet. Scroll up a little and try again.",HEADER:"**Channel stats** from the last {count, plural, one {# loaded message} other {# loaded messages}}, since {since}",TOP_POSTERS:"**Who talks most**",POSTER:"{rank}. {name}: {count} ({share}%)",BUSIEST_HOURS:"**Busiest hours**: {hours}",HOUR:"{hour}:00 ({count})",PER_DAY:"**Per day**: about {count, plural, one {# message} other {# messages}}"}),messages=locales.messages,format=locales.format;function channelStats(messages,hourOf=timestamp=>new Date(timestamp).getHours()){if(messages.length){var byAuthor=new Map,byHour=new Map,since=1/0,until=-1/0;for(var{authorId,authorName,timestamp}of messages){var author=byAuthor.get(authorId)??{name:authorName,count:0};author.count++,byAuthor.set(authorId,author),byHour.set(hourOf(timestamp),(byHour.get(hourOf(timestamp))??0)+1),since=Math.min(since,timestamp),until=Math.max(until,timestamp)}var posters=[...byAuthor.values()].sort((left,right)=>right.count-left.count).slice(0,5).map(({name,count})=>({name,count,share:Math.round(count/messages.length*100)})),hours=[...byHour.entries()].sort((left,right)=>right[1]-left[1]||left[0]-right[0]).slice(0,3).map(([hour,count])=>({hour,count})),days=Math.max(1,(until-since)/864e5);return{count:messages.length,since,posters,hours,perDay:Math.round(messages.length/days)}}}function readMessage({author,timestamp}){var at=void 0===timestamp?0/0:new Date(timestamp.valueOf()).getTime();if(!(!author?.id||Number.isNaN(at)))return{authorId:author.id,authorName:author.globalName||author.username||author.id,timestamp:at}}function loadedMessages(channelId){var store=unbound.flux.getStore("Message");return(store.getMessages(channelId)?.toArray?.()??[]).flatMap(message=>readMessage(message)??[])}function statsText(stats){return[format("HEADER",{count:stats.count,since:new Date(stats.since).toLocaleDateString()}),messages.TOP_POSTERS,...stats.posters.map((poster,index)=>format("POSTER",{rank:index+1,...poster})),format("BUSIEST_HOURS",{hours:stats.hours.map(({hour,count})=>format("HOUR",{hour:String(hour).padStart(2,"0"),count})).join(", ")}),format("PER_DAY",{count:stats.perDay})].join("\n")}function registerChannelStats(){unbound.commands.register({channelstats:{description:"STATS_DESC",execute(_options,{channel}){var stats=channelStats(loadedMessages(channel.id));return{content:stats?statsText(stats):messages.NO_MESSAGES,ephemeral:!0}}}})}return locales.useMessages,{start:function start(){registerChannelStats()}}}();return this.__plugin;}})